WITH -- Attachment rows only exist on messages flagged has_attachments, so -- the partial index on that flag finds every document. Carrying the -- output columns here avoids reading each message row a second time. mailbox_documents AS MATERIALIZED ( SELECT a.id AS attachment_db_id, m.provider_id AS email_provider_id, a.provider_attachment_id, a.filename, a.mime_type, m.internal_date_ts, m.id AS message_db_id, m.thread_id AS thread_db_id, m.from_contact_id, m.subject FROM public.email_messages m JOIN public.email_attachments a ON a.message_id = m.id WHERE m.link_id = $1 AND m.has_attachments = true AND a.filename IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM public.document_email de JOIN public."Document" d ON d.id = de.document_id WHERE de.email_attachment_id = a.id AND d."deletedAt" IS NULL ) -- attachment mime type filters injected below AND a.reference_url IS NULL AND ( a.mime_type IN ( 'application/pdf', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', 'application/msword', 'text/html', 'text/plain', 'pdf' ) OR ( a.mime_type = 'application/octet-stream' AND UPPER(SUBSTRING(a.filename FROM '\.([^.]+)$')) IN ('PDF', 'DOC', 'DOCX', 'TXT', 'HTML') ) ) ), -- Everyone the user has sent mail to, except the user. contacted AS MATERIALIZED ( SELECT DISTINCT recipient.contact_id FROM public.email_messages sent_message JOIN public.email_message_recipients recipient ON recipient.message_id = sent_message.id WHERE sent_message.link_id = $1 AND sent_message.is_sent = true AND NOT EXISTS ( SELECT 1 FROM public.email_links l JOIN public.email_contacts c ON c.link_id = l.id AND LOWER(c.email_address) = LOWER(l.email_address) WHERE l.id = $1 AND c.id = recipient.contact_id ) ), document_threads AS MATERIALIZED ( SELECT DISTINCT thread_db_id AS thread_id FROM mailbox_documents ), -- Senders come from an index alone; most threads qualify here. sender_qualified_threads AS MATERIALIZED ( SELECT DISTINCT sender_message.thread_id FROM document_threads JOIN public.email_messages sender_message ON sender_message.thread_id = document_threads.thread_id JOIN contacted ON contacted.contact_id = sender_message.from_contact_id ), -- Recipients need each message row, so only check the threads no -- sender qualified. qualified_threads AS ( SELECT thread_id FROM sender_qualified_threads UNION SELECT thread_message.thread_id FROM document_threads JOIN public.email_messages thread_message ON thread_message.thread_id = document_threads.thread_id JOIN public.email_message_recipients recipient ON recipient.message_id = thread_message.id JOIN contacted ON contacted.contact_id = recipient.contact_id WHERE NOT EXISTS ( SELECT 1 FROM sender_qualified_threads WHERE sender_qualified_threads.thread_id = document_threads.thread_id ) ) SELECT document.attachment_db_id, document.email_provider_id, document.provider_attachment_id, document.filename, document.mime_type, document.internal_date_ts, document.message_db_id, document.thread_db_id, from_contact.email_address AS sender_email, document.subject FROM mailbox_documents document JOIN qualified_threads ON qualified_threads.thread_id = document.thread_db_id JOIN public.email_contacts from_contact ON from_contact.id = document.from_contact_id ORDER BY document.internal_date_ts DESC
